questions.solution:
from pathlib import Path


def inside(root: str, token: str) -> bool:
    """True if `token`, taken relative to `root` (or absolute), names a path inside the jail `root`."""
    jail = Path(root).resolve()
    return (jail / token).resolve().is_relative_to(jail)
